lab.solution:
def choose_export_dir(value):
    allowed={'exports','practice_exports'}
    if value not in allowed:
        raise ValueError('unsupported export directory')
    return value

lab.testCode:
assert choose_export_dir('exports')=='exports'
assert choose_export_dir('practice_exports')=='practice_exports'
for bad in ('../private','',None):
    try: choose_export_dir(bad)
    except ValueError: pass
    else: raise AssertionError('unsupported directory accepted')
